import 'dart:convert';

/// Typed views over the content bundle. The bundle is generated by
/// `tools/paluma_cli`; see docs/content-model.md.

/// A `lat`/`lon` pair in WGS84.
class GeoPoint {
  const GeoPoint(this.lat, this.lon);

  final double lat;
  final double lon;

  factory GeoPoint.fromJson(Map<String, Object?> json) => GeoPoint(
    (json['lat']! as num).toDouble(),
    (json['lon']! as num).toDouble(),
  );
}

class Park {
  const Park({
    required this.id,
    required this.name,
    required this.region,
    required this.center,
    required this.bounds,
    required this.defaultZoom,
    required this.updated,
    required this.disclaimer,
    required this.emergencyPhone,
    this.emergencyAlternativePhone = '112',
    required this.emergencyNotes,
    required this.attributions,
  });

  final String id;
  final String name;
  final String region;
  final GeoPoint center;
  final ParkBounds bounds;
  final double defaultZoom;
  final String updated;
  final String disclaimer;
  final String emergencyPhone;

  /// The number to try when [emergencyPhone] does not connect, normally 112.
  final String emergencyAlternativePhone;
  final String emergencyNotes;
  final List<Attribution> attributions;

  factory Park.fromJson(Map<String, Object?> json) {
    final emergency = json['emergency'] as Map<String, Object?>? ?? const {};
    return Park(
      id: json['id']! as String,
      name: json['name']! as String,
      region: json['region']! as String,
      center: GeoPoint.fromJson(json['center']! as Map<String, Object?>),
      bounds: ParkBounds.fromJson(json['bounds']! as Map<String, Object?>),
      defaultZoom: ((json['default_zoom'] as num?) ?? 12).toDouble(),
      updated: json['updated']! as String,
      disclaimer: (json['disclaimer'] as String?) ?? '',
      emergencyPhone: (emergency['phone'] as String?) ?? '000',
      emergencyAlternativePhone:
          (emergency['alternative_phone'] as String?) ?? '112',
      emergencyNotes: (emergency['notes'] as String?) ?? '',
      attributions: ((json['attribution'] as List?) ?? const [])
          .cast<Map<String, Object?>>()
          .map(Attribution.fromJson)
          .toList(growable: false),
    );
  }
}

class ParkBounds {
  const ParkBounds({
    required this.north,
    required this.south,
    required this.east,
    required this.west,
  });

  final double north;
  final double south;
  final double east;
  final double west;

  factory ParkBounds.fromJson(Map<String, Object?> json) => ParkBounds(
    north: (json['north']! as num).toDouble(),
    south: (json['south']! as num).toDouble(),
    east: (json['east']! as num).toDouble(),
    west: (json['west']! as num).toDouble(),
  );
}

class Attribution {
  const Attribution({required this.label, required this.licence, this.url});

  final String label;
  final String licence;
  final String? url;

  factory Attribution.fromJson(Map<String, Object?> json) => Attribution(
    label: json['label']! as String,
    licence: json['licence']! as String,
    url: json['url'] as String?,
  );
}

/// Offline safety guidance, kept in the bundle so it is always available
/// without a signal. See `content/data/paluma/safety.json`.
class SafetyContent {
  const SafetyContent({
    required this.updated,
    required this.intro,
    required this.emergencyHeadline,
    required this.emergencySteps,
    required this.sections,
  });

  final String updated;
  final String intro;
  final String emergencyHeadline;
  final List<String> emergencySteps;
  final List<SafetySection> sections;

  static const empty = SafetyContent(
    updated: '',
    intro: '',
    emergencyHeadline: '',
    emergencySteps: [],
    sections: [],
  );

  factory SafetyContent.fromJson(Map<String, Object?> json) {
    final emergency = json['emergency'] as Map<String, Object?>? ?? const {};
    return SafetyContent(
      updated: (json['updated'] as String?) ?? '',
      intro: (json['intro'] as String?) ?? '',
      emergencyHeadline: (emergency['headline'] as String?) ?? '',
      emergencySteps: ((emergency['steps'] as List?) ?? const [])
          .cast<String>()
          .toList(growable: false),
      sections: ((json['sections'] as List?) ?? const [])
          .cast<Map<String, Object?>>()
          .map(SafetySection.fromJson)
          .toList(growable: false),
    );
  }
}

class SafetySection {
  const SafetySection({required this.title, required this.items});

  final String title;
  final List<String> items;

  factory SafetySection.fromJson(Map<String, Object?> json) => SafetySection(
    title: json['title']! as String,
    items: ((json['items'] as List?) ?? const []).cast<String>().toList(
      growable: false,
    ),
  );
}

/// A numbered junction marker on a track.
class Junction {
  const Junction({
    required this.id,
    required this.number,
    required this.location,
    this.name,
    this.notes,
    this.water,
    this.reception,
    this.unverified = false,
  });

  final String id;
  final int number;
  final String? name;
  final GeoPoint location;
  final String? notes;
  final bool? water;
  final bool? reception;
  final bool unverified;

  String get label =>
      name == null || name!.isEmpty ? 'Junction $number' : name!;

  factory Junction.fromJson(Map<String, Object?> json) => Junction(
    id: json['id']! as String,
    number: json['number']! as int,
    name: json['name'] as String?,
    location: GeoPoint.fromJson(json['location']! as Map<String, Object?>),
    notes: json['notes'] as String?,
    water: json['water'] as bool?,
    reception: json['reception'] as bool?,
    unverified: (json['unverified'] as bool?) ?? false,
  );
}

class Poi {
  const Poi({
    required this.id,
    required this.name,
    required this.category,
    required this.location,
    this.summary,
    this.description,
    this.qrId,
    this.unverified = false,
    this.sources = const [],
  });

  final String id;
  final String name;
  final String category;
  final GeoPoint location;
  final String? summary;
  final String? description;
  final String? qrId;
  final bool unverified;
  final List<PoiSource> sources;

  factory Poi.fromJson(Map<String, Object?> json) => Poi(
    id: json['id']! as String,
    name: json['name']! as String,
    category: json['category']! as String,
    location: GeoPoint.fromJson(json['location']! as Map<String, Object?>),
    summary: json['summary'] as String?,
    description: json['description'] as String?,
    qrId: json['qr_id'] as String?,
    unverified: (json['unverified'] as bool?) ?? false,
    sources: ((json['sources'] as List?) ?? const [])
        .cast<Map<String, Object?>>()
        .map(PoiSource.fromJson)
        .toList(growable: false),
