}

class PoiSource {
  const PoiSource({required this.label, this.url});

  final String label;
  final String? url;

  factory PoiSource.fromJson(Map<String, Object?> json) =>
      PoiSource(label: json['label']! as String, url: json['url'] as String?);
}

/// One junction-to-junction stretch of a track.
class Segment {
  const Segment({
    required this.from,
    required this.to,
    required this.trackId,
    required this.trackName,
    required this.distanceM,
    required this.walkMinutes,
    required this.bearingDeg,
    this.ascentM,
    this.descentM,
  });

  final String from;
  final String to;
  final String trackId;
  final String trackName;
  final int distanceM;
  final int walkMinutes;
  final double bearingDeg;

  /// Climb walking `from` → `to`.
  final double? ascentM;

  /// Drop walking `from` → `to`, which is the climb walking the other way.
  final double? descentM;

  /// The junction at the other end of this segment from [junctionId], or null
  /// when the segment does not touch it.
  String? otherEnd(String junctionId) {
    if (from == junctionId) return to;
    if (to == junctionId) return from;
    return null;
  }

  /// The compass bearing walked when starting at [junctionId].
  double bearingFrom(String junctionId) =>
      from == junctionId ? bearingDeg : (bearingDeg + 180) % 360;

  /// The climb walked when starting at [junctionId].
  double? ascentFrom(String junctionId) =>
      from == junctionId ? ascentM : descentM;

  factory Segment.fromJson(Map<String, Object?> json) => Segment(
    from: json['from']! as String,
    to: json['to']! as String,
    trackId: json['track_id']! as String,
    trackName: (json['track_name'] as String?) ?? '',
    distanceM: json['distance_m']! as int,
    walkMinutes: json['walk_minutes']! as int,
    bearingDeg: (json['bearing_deg']! as num).toDouble(),
    ascentM: (json['ascent_m'] as num?)?.toDouble(),
    descentM: (json['descent_m'] as num?)?.toDouble(),
  );
}

/// How the walking times in the bundle were computed, so the app can be honest
/// about them.
class EstimateInfo {
  const EstimateInfo({
    required this.method,
    required this.paceKmh,
    required this.includesElevation,
    required this.label,
  });

  final String method;
  final double paceKmh;
  final bool includesElevation;
  final String label;

  factory EstimateInfo.fromJson(Map<String, Object?> json) => EstimateInfo(
    method: json['method']! as String,
    paceKmh: (json['pace_kmh']! as num).toDouble(),
    includesElevation: json['includes_elevation']! as bool,
    label: json['label']! as String,
  );
}

/// A summary of one polyline in the bundle (the geometry itself is handed to
/// MapLibre as raw GeoJSON).
class TrackSummary {
  const TrackSummary({
    required this.id,
    required this.trackClass,
    required this.lengthM,
    this.name,
    this.unverified = false,
  });

  final String id;
  final String? name;
  final String trackClass;
  final double lengthM;
  final bool unverified;

  String get label => name ?? 'Connector';

  factory TrackSummary.fromJson(Map<String, Object?> properties) =>
      TrackSummary(
        id: properties['id']! as String,
        name: properties['name'] as String?,
        trackClass: (properties['class'] as String?) ?? 'track',
        lengthM: ((properties['length_m'] as num?) ?? 0).toDouble(),
        unverified: (properties['unverified'] as bool?) ?? false,
      );
}

class BundleFile {
  const BundleFile({required this.path, required this.bytes});

  final String path;
  final int bytes;
}

class BundleManifest {
  const BundleManifest({
    required this.schemaVersion,
    required this.bundleVersion,
    required this.generator,
    required this.park,
    required this.files,
    required this.totalBytes,
  });

  final int schemaVersion;
  final String bundleVersion;
  final String generator;
  final String park;
  final List<BundleFile> files;
  final int totalBytes;

  factory BundleManifest.fromJson(Map<String, Object?> json) {
    final totals = json['totals'] as Map<String, Object?>? ?? const {};
    return BundleManifest(
      schemaVersion: json['schema_version']! as int,
      bundleVersion: json['bundle_version']! as String,
      generator: (json['generator'] as String?) ?? '',
      park: (json['park'] as String?) ?? '',
      files: ((json['files'] as List?) ?? const [])
          .cast<Map<String, Object?>>()
          .map(
            (f) => BundleFile(
              path: f['path']! as String,
              bytes: f['bytes']! as int,
            ),
          )
          .toList(growable: false),
      totalBytes: ((totals['bytes'] as num?) ?? 0).toInt(),
    );
  }
}

/// Decodes a JSON string into a `Map<String, Object?>`.
Map<String, Object?> decodeJsonObject(String source) {
  final decoded = jsonDecode(source);
  if (decoded is! Map<String, Object?>) {
    throw FormatException('Expected a JSON object, got ${decoded.runtimeType}');
  }
  return decoded;
}
